    { source: "ABC", target: "XYZ", value: 100, reduction: 20 },
    { source: "XYZ", target: "DEF", value: 80, reduction: 10 },
    { source: "ABC", target: "DEF", value: 20, reduction: 5 }
];

sankey.links(links);

// draw the Sankey chart
svg.append("g")
    .selectAll("path")
    .data(sankey.links())
    .enter()
    .append("path")
    .attr("d", function(d) {
        return "M" + d.source.x + "," + d.source.y + "L" + d.target.x + "," + d.target.y;
    })
    .attr("stroke-width", function(d) {
        return d.reduction * 2; // make the link thicker at the beginning and thinner at the end
    });

// add the labels
